'use client';

import { useEffect } from 'react';

interface WelcomeComponentProps {
  pageName: string;
}

/**
 * Analytics logging service that doesn't block the response.
 * Uses unstable_after to schedule work after the response is sent.
 */
async function logPageView(pageName: string): Promise<void> {
  try {
    // Simulate analytics API call
    const response = await fetch('/api/analytics', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        event: 'page_view',
        page: pageName,
        timestamp: Date.now(),
        userAgent: navigator.userAgent
      }),
    });

    if (!response.ok) {
      console.warn('Analytics logging failed:', response.status);
    }
  } catch (error) {
    console.warn('Analytics logging error:', error);
  }
}

/**
 * Server component that displays a welcome message and logs page views.
 * The analytics logging is scheduled after the response is sent using unstable_after.
 */
export default function WelcomeComponent({ pageName }: WelcomeComponentProps) {
  useEffect(() => {
    // Schedule analytics logging after the component mounts
    // This ensures the logging doesn't block the initial response
    if (typeof window !== 'undefined') {
      // Use React's startTransition for client-side scheduling
      import('react').then(({ startTransition }) => {
        startTransition(() => {
          logPageView(pageName).catch(console.warn);
        });
      });
    }
  }, [pageName]);

  return (
    <div style={{ padding: '2rem', textAlign: 'center' }}>
      <h1>Welcome to {pageName}!</h1>
      <p>This page view is being logged to analytics asynchronously.</p>
      <p style={{ color: '#666', fontSize: '0.9rem' }}>
        The analytics request will complete after this page loads.
      </p>
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
  try {
    const data = await request.json();

    // Simulate analytics processing
    console.log('Analytics event logged:', {
      event: data.event,
      page: data.page,
      timestamp: new Date(data.timestamp).toISOString(),
      userAgent: data.userAgent
    });

    // Simulate some processing time
    await new Promise(resolve => setTimeout(resolve, 100));

    return NextResponse.json({ 
      success: true, 
      message: 'Page view logged successfully' 
    });
  } catch (error) {
    console.error('Analytics logging failed:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to log page view' },
      { status: 500 }
    );
  }
}

