  try {
    // Use unstable_after to schedule work after the response is sent
    // This is the recommended Next.js approach for non-blocking analytics
    if (typeof unstable_after === 'function') {
      unstable_after(async () => {
        try {
          const response = await fetch('/api/analytics', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              event: 'page_view',
              page: pageName,
              timestamp: Date.now(),
              source: 'server'
            }),
          });

          if (!response.ok) {
            console.warn('Server analytics logging failed:', response.status);
          }
        } catch (error) {
          console.warn('Server analytics logging error:', error);
        }
      });
    }
  } catch (error) {
    console.warn('Analytics scheduling error:', error);
  }
}

